export function uniqueOpts(values: Array<string | undefined>): SelectOption[] {
  return [...new Set(values.filter((v): v is string => Boolean(v && v.trim() && v !== "-")))]
    .sort((a, b) => a.localeCompare(b, "pt"))
    .map(value => ({ value }));
}

export function matchesFilter(row: string | undefined, filtro: string) {
  if (!filtro) return true;
  const r = (row ?? "").toLowerCase();
  const f = filtro.toLowerCase();
  return r === f || r.includes(f) || f.includes(r);
}

export type ViewFilterField = {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: SelectOption[];
  placeholder?: string;
};

export function ViewFilters({
  accent = "gold",
  fields = [],
  chips,
  onClear,
  action,
}: {
  accent?: "gold" | "fin";
  fields?: ViewFilterField[];
  chips?: { options: string[]; value: string; onChange: (v: string) => void };
  onClear?: () => void;
  action?: ReactNode;
}) {
  const chipsOn = Boolean(chips && chips.value && chips.value !== "Todos" && chips.value !== "Todas");
  const active = fields.some(f => f.value) || chipsOn;
  const cols = fields.length + (action ? 1 : 0);
  const grid = cols <= 1
    ? "grid-cols-1 sm:grid-cols-[1fr_auto]"
    : cols === 2
      ? "grid-cols-1 sm:grid-cols-2"
      : "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3";

  return (
    <div className="rounded-xl border border-slate-200 bg-white p-4 space-y-3">
      {(fields.length > 0 || action) && (
        <div className={`grid ${grid} gap-3 items-end`}>
          {fields.map(f => (
            <div key={f.label}>
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">{f.label}</label>
              <SearchSelect
                value={f.value}
                onChange={f.onChange}
                options={f.options}
                placeholder={f.placeholder ?? `Pesquisar ${f.label.toLowerCase()}…`}
                allowEmpty
              />
            </div>
          ))}
          {action}
        </div>
      )}
      {(chips || active) && (
        <div className="flex flex-wrap items-center justify-between gap-2">
          {chips
            ? <FilterChips options={chips.options} value={chips.value} onChange={chips.onChange} accent={accent} />
            : <span />}
          {active && onClear && (
            <button type="button" onClick={onClear} className="text-xs font-semibold text-slate-500 hover:text-slate-800 whitespace-nowrap">
              Limpar filtros
            </button>
          )}
        </div>
      )}
    </div>
  );
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { apiCreateFormador, apiDeleteFormador, apiPatchFormador } from "./api";
import { formadoresAtivos, formadorSub, FORMADORES_SEED, type Formador, type FormadorRegime } from "./formadorModel";
import { formadoresOptsWithFrom, formadoresToOpts, type SelectOption } from "./FormKit";
import { loadOps } from "./opsCache";

type FormadoresCtx = {
  formadores: Formador[];
  addFormador: (f: Omit<Formador, "id">) => Formador;
  patchFormador: (id: number, patch: Partial<Formador>) => void;
  removeFormador: (id: number) => void;
  options: (current?: string | string[], regime?: FormadorRegime) => SelectOption[];
};

const Ctx = createContext<FormadoresCtx | null>(null);

function asFormador(r: { id: number; nome: string; telf: string; email: string; especialidade: string; ccp: string; nif: string; regimes: string[]; estado: string }): Formador {
  return {
    id: r.id,
    nome: r.nome,
    telf: r.telf,
    email: r.email,
    especialidade: r.especialidade,
    ccp: r.ccp,
    nif: r.nif,
    regimes: r.regimes.filter((x): x is FormadorRegime => x === "gold" || x === "fin"),
    estado: r.estado === "Inactivo" ? "Inactivo" : "Ativo",
  };
}

export function FormadoresProvider({ children }: { children: ReactNode }) {
  const [formadores, setFormadores] = useState<Formador[]>(() => FORMADORES_SEED.map(f => ({ ...f, regimes: [...f.regimes] })));

  useEffect(() => {
    let alive = true;
    loadOps().then(snap => {
      if (!alive) return;
      setFormadores(snap.formadores.map(asFormador));
    }).catch(() => undefined);
    return () => { alive = false; };
  }, []);

  const addFormador = useCallback((draft: Omit<Formador, "id">) => {
    const created: Formador = { ...draft, id: Date.now() % 100000 };
    setFormadores(xs => [created, ...xs]);
    void apiCreateFormador(created).then(r => {
      if (r.formador) setFormadores(xs => xs.map(f => f.id === created.id ? asFormador(r.formador) : f));
    }).catch(() => undefined);
    return created;
  }, []);

  const patchFormador = useCallback((id: number, patch: Partial<Formador>) => {
    setFormadores(xs => xs.map(f => f.id === id ? { ...f, ...patch } : f));
    void apiPatchFormador(id, patch).catch(() => undefined);
  }, []);

  const removeFormador = useCallback((id: number) => {
    setFormadores(xs => xs.filter(f => f.id !== id));
    void apiDeleteFormador(id).catch(() => undefined);
  }, []);

  const options = useCallback((current?: string | string[], regime?: FormadorRegime) => {
    return formadoresOptsWithFrom(formadoresToOpts(formadoresAtivos(formadores, regime)), current);
  }, [formadores]);

  const value = useMemo(() => ({
    formadores, addFormador, patchFormador, removeFormador, options,
  }), [formadores, addFormador, patchFormador, removeFormador, options]);

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useFormadores() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useFormadores precisa de FormadoresProvider");
  return ctx;
}

export function useFormadorOptions(current?: string | string[], regime?: FormadorRegime) {
  const { formadores } = useFormadores();
  return formadoresOptsWithFrom(formadoresToOpts(formadoresAtivos(formadores, regime)), current);
}

export function useFormadorByNome(nome: string | undefined) {
  const { formadores } = useFormadores();
  if (!nome?.trim()) return undefined;
  return formadores.find(f => f.nome === nome);
}

